832	    filename: &str,
833	) -> Response {
834	    let name = match PackageName::parse(raw_name) {
835	        Ok(n) => n,
836	        Err(err) => return error_response(&err),
837	    };
838	    let (filename, version) = match name.parse_tarball_name(filename) {
839	        Ok(parsed) => parsed,
840	        Err(err) => return error_response(&err),
841	    };
842	    if let Err(err) = authorize(state, identity, name.as_str(), Action::Access) {
843	        return error_response(&err);
844	    }
845	    if let Err(err) = ensure_osv_allowed(state, &name, &version) {
846	        return error_response(&err);
847	    }
848	
849	    // The hosted store is authoritative. A genuine fault here (not a
850	    // plain miss, which surfaces as `Ok(None)`) must fail closed rather
851	    // than fall through to upstream and serve bytes of a different
852	    // provenance for the same package name.
853	    match state.inner.storage.open_hosted_tarball(&name, &filename).await {
854	        Ok(Some((body, len))) => return tarball_response(body, len),
855	        Ok(None) => {}
