963	fn expected_tarball_integrity(
964	    packument: &[u8],
965	    name: &PackageName,
966	    filename: &str,
967	    version: &str,
968	) -> Result<Option<Integrity>, RegistryError> {
969	    let packument: Value = serde_json::from_slice(packument)?;
970	    let Some(manifest) = packument
971	        .get("versions")
972	        .and_then(Value::as_object)
973	        .and_then(|versions| versions.get(version))
974	    else {
975	        return Ok(None);
976	    };
977	    let declared = manifest
978	        .get("dist")
979	        .and_then(|dist| dist.get("integrity"))
980	        .and_then(Value::as_str)
981	        .ok_or_else(|| {
982	            tarball_integrity_error(
983	                name,
984	                filename,
985	                format!("packument has no dist.integrity for version {version:?}"),
986	            )
987	        })?;
988	    streaming::parse_integrity(declared).map(Some).map_err(|err| {
989	        tarball_integrity_error(name, filename, format!("malformed dist.integrity: {err}"))
990	    })
991	}
