1	//! End-to-end tests for static-serve mode against a synthetic
2	//! verdaccio-shaped storage built in a `TempDir` (see `common`). The
3	//! packuments carry the rich publish metadata verdaccio/npm emit
4	//! (`_attachments`, `_nodeVersion`, `contributors`, ...) so these tests
5	//! assert that pnpr rewrites tarball URLs and abbreviates that
6	//! format correctly without any upstream proxy.
7	
8	// `#[path]` rather than the `tests/common/mod.rs` layout, which the
9	// Perfectionist dylint forbids.
10	#[path = "common/storage.rs"]
11	mod common;
12	
13	use axum::{
14	    body::{Body, to_bytes},
15	    http::{Request, StatusCode},
16	};
17	use pnpr::{Config, router};
18	use serde_json::Value;
19	use std::{
20	    net::{Ipv4Addr, SocketAddr, SocketAddrV4},
21	    path::PathBuf,
22	};
23	use tower::ServiceExt;
