25	const PUBLIC_URL: &str = "http://example.test";
26	
27	fn static_config(storage: PathBuf) -> Config {
28	    let listen = SocketAddr::V4(SocketAddrV4::new(Ipv4Addr::LOCALHOST, 4873));
29	    let mut config = Config::static_serve(listen, storage);
30	    config.public_url = PUBLIC_URL.to_string();
31	    config
32	}
