/// stripping any query string (`?…`) or URL fragment (`#…`). Returns
/// `Some(basename)` when the URL has a non-empty last path segment, or
/// `None` when it ends in a trailing slash or has no usable segment.
///
/// This is a deliberately syntactic split — no percent-decoding or
/// traversal check — so the caller stays in charge of validating the
/// result before it reaches a filesystem path or an upstream URL.
pub fn tarball_basename(url: &str) -> Option<&str> {
    // A fragment can only appear after the path (and after any query),
    // so strip it first, then the query, then take the last path segment.
    let path = url.split(['#', '?']).next().unwrap_or(url);
    let basename = path.rsplit('/').next()?;
    (!basename.is_empty()).then_some(basename)
}

